from cards.pack import *

# ---------------------------------------------------------------------------
# La RESERVE — mecanique maison du pack Brawn (auteur « Rainy »)
#
# L'insert la definit ainsi :
#   « Reserve is an out of play area that functions in a similar manner to the
#     hand. A player can play a card from their reserve, paying its costs.
#     Resources generated by discarding cards from a player's hand cannot be
#     used to pay for cards in a player's reserve. […] A player may only have 3
#     cards in their reserve at any given time. »
#
# La zone elle-meme vit dans le moteur (`player.reserve`, DeckType.ReserveArea,
# voir les # CORRECTIF de game/deck/deck_type.py, game/player/player.py,
# game/card/card.py et game/ability/factory/resources.py). Ce fichier ne porte
# que ce qui est propre AUX CARTES : mettre en reserve, et reagir a une carte
# jouee depuis la reserve.
# ---------------------------------------------------------------------------


def MettreEnReserve(faces: Sequence['CardFace'], player: 'Player', effect: 'Effect') -> Sequence['CardFace']:
    """Pose des cartes en reserve et fait redescendre a la limite de 3.

    Passe TOUJOURS par `player.PutIntoReserve`, seul endroit qui applique la
    limite : une carte peut entrer au-dela de 3, mais il faut alors defausser
    tout de suite, et c'est au joueur de choisir laquelle.
    """
    if not faces:
        return []
    return player.PutIntoReserve(faces, effect)


def RecyclerVersLaReserve(this: 'CardFace', joueur: 'Player', effect: 'Effect') -> None:
    """« Put this card into your reserve » pour une carte en cours de resolution.

    Un EVENEMENT est defausse par le moteur APRES la resolution de son effet :
    deplacer la carte soi-meme depuis l'operation ne sert donc a rien, elle
    repart en defausse dans la foulee. Mesure faite le 7/8/2026 sur Calculated
    Defense — la condition etait bel et bien vraie (paye='BB', zone = la main),
    la carte finissait quand meme en defausse.

    Le bon crochet est `Message.WhenCardWouldDiscard`, qui expose `SetToArea` :
    on ne deplace pas la carte, on DETOURNE sa defausse a venir. Modele de Front
    Organization 50028, qui s'en sert pour se defausser a la place d'une autre.
    """
    def rediriger(effet_temp: 'Effect', message: 'Message.WhenCardWouldDiscard') -> None:
        # ⚠ Le moteur envoie CE MESSAGE PLUSIEURS FOIS pour une meme carte (4
        # fois, mesure du 7/8/2026) : les premiers envois sont des controles,
        # seul le dernier defausse pour de bon. Avec `unregister_after_exec=True`
        # l'abilite disparaissait donc apres un simple controle, et la vraie
        # defausse partait sans redirection. Elle reste donc armee...
        #
        # ... mais elle ne doit surtout PAS rediriger une defausse VENANT de la
        # reserve : la carte y resterait pour toujours, y compris quand la limite
        # de 3 veut l'en sortir. D'ou le filtre sur la zone de traitement, seule
        # zone d'ou part la defausse de fin de resolution.
        if not this.card.area.flags.is_processing:
            return
        message.SetToArea(joueur.reserve)
        # La carte n'est pas encore posee : on redescend a 3 juste apres, et
        # c'est au joueur de choisir ce qui part.
        joueur.EnforceReserveLimit(effet_temp)

    this.effect.RegisterTemp(
        AbilityFactory.WhenCardWouldDiscard(
            AbilityType.Temp0,
            "This",
            rediriger,
        ),
        unregister_after_exec=False,
        until_round_end=True,
    )


def EstJoueeDepuisLaReserve(effect: 'Effect', message: 'Message.AfterPlayerPlayedCard') -> bool:
    """« Apres que tu as joue une carte depuis ta reserve »."""
    joueur = effect.GetInitiator()
    if not isinstance(joueur, Player):
        return False
    if message.GetToPlayer() != joueur:
        return False
    return message.from_area == joueur.reserve


def EstJoueeDepuisLaMain(effect: 'Effect', message: 'Message.AfterPlayerPlayedCard') -> bool:
    """« Apres que tu as joue cette carte DEPUIS TA MAIN ».

    `message.is_like_from_hand` ne suffit pas : la reserve est justement une
    zone « comme la main », donc ce drapeau y est vrai lui aussi. Les cartes qui
    impriment « from your hand » (Silk, Calculated Defense, Gamma Strike) ont
    besoin de la vraie zone, sans quoi elles se declencheraient depuis la
    reserve — et l'insert dit explicitement le contraire pour Silk.
    """
    joueur = message.GetToPlayer()
    return message.from_area == joueur.hand_cards


def ApresCarteJoueeDepuisLaReserve(ability_type: 'AbilityType',
                                   operation: Callable[['Effect', 'Message.AfterPlayerPlayedCard'], None],
                                   *,
                                   hero_form_only: bool=False,
                                   ) -> 'Ability':
    """Fabrique commune a Brawn's Suit, Forward-Thinking et Totally Awesome.

    Les trois impriment la meme condition (« After you play a card from your
    reserve ») pour trois effets differents.
    """
    conditions = [EstJoueeDepuisLaReserve]
    if hero_form_only:
        conditions.append(
            lambda effect, message: message.GetToPlayer().IsHero()
        )

    return AbilityFactory.AfterPlayerPlayedCard(
        ability_type,
        "You",
        None,
        operation,
        conditions=conditions,
    )
